//! stan-model-rs: a Rust-native runtime that executes Stan models.
//!
//! A model is Rust code (generated by stanc-rs or written by hand) that implements
//! [`StanModel`]. Its log density is generic in the scalar type, so the same code runs with `f64`
//! values, with stanmath-rs reverse-mode variables for gradients, and with nested forward-over-
//! reverse variables for Hessians. Every [`StanModel`] is also a [`Model`], the object-safe
//! interface that inference algorithms use:
//!
//! ```
//! use stan_model_rs::{Data, LogDensityOptions, Model};
//! use stan_model_rs_fixtures::NormalMean;
//!
//! let model = NormalMean::new(&Data::from_json_str(r#"{"y": 1.5}"#)?)?;
//! let (lp, grad) = model.log_density_gradient(&[0.3], LogDensityOptions::default())?;
//! // d/dmu [log N(mu | 0, 5) + log N(y | mu, 1)] = -mu / 25 + (y - mu)
//! assert!((grad[0] - (-0.3 / 25.0 + 1.2)).abs() < 1e-12);
//! # let _ = lp;
//! # Ok::<(), stan_model_rs::ModelError>(())
//! ```
//!
//! The runtime owns the execution contract: metadata and parameter ordering, data input and
//! validation, the composition of constraining transforms and their Jacobians, and the
//! evaluation drivers. The mathematics (special functions, densities, transforms, automatic
//! differentiation) comes from stanmath-rs.

pub mod data;
pub mod error;
pub mod meta;
pub mod model;
#[cfg(feature = "nuts")]
pub mod nuts;
pub mod print;
pub mod rng;
pub mod transform;

pub use data::Data;
pub use error::{ErrorKind, ModelError, Result, fatal_error, locate, reject};
pub use meta::{BaseType, Block, Bound, Constraint, ModelInfo, Outputs, VarInfo};
pub use model::{GradientCheck, LogDensityOptions, Model, StanModel};
pub use transform::{Bounds, Reader};

pub use rand;
pub use stanmath_rs;
pub use stanmath_rs::prelude::Real;

/// Version of this runtime.
pub const RUNTIME_VERSION: &str = concat!("stan-model-rs ", env!("CARGO_PKG_VERSION"));

/// The stanmath-rs revision this runtime is built against.
pub const MATH_VERSION: &str = "stanmath-rs 0.1.0 (04dc871)";
